"""Writing numbers."""


def ordinal(n: int) -> str:
    """1st, 2nd, 3rd, 4th and so on."""
    suffix = "th" if 10 <= n % 100 <= 20 else {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"


_NUMERALS = ((1000, "M"), (500, "D"), (100, "C"), (50, "L"), (10, "X"), (5, "V"), (1, "I"))


def to_roman(n: int) -> str:
    """``n`` in Roman numerals, for 1 to 3999."""
    if not 1 <= n <= 3999:
        raise ValueError(f"{n} is outside 1 to 3999")
    letters = []
    for value, numeral in _NUMERALS:
        count, n = divmod(n, value)
        letters.append(numeral * count)
    return "".join(letters)

import unittest

from numerals import ordinal, to_roman


class OrdinalTest(unittest.TestCase):
    def test_ordinals(self) -> None:
        self.assertEqual([ordinal(n) for n in (1, 2, 3, 4, 11)], ["1st", "2nd", "3rd", "4th", "11th"])


class RomanTest(unittest.TestCase):
    def test_numbers(self) -> None:
        self.assertEqual(to_roman(1), "I")
        self.assertEqual(to_roman(3), "III")
        self.assertEqual(to_roman(2023), "MMXXIII")

    def test_out_of_range(self) -> None:
        for n in (0, 4000):
            with self.assertRaises(ValueError):
                to_roman(n)


if __name__ == "__main__":
    unittest.main()
